"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[632],{632:t=>{t.exports=JSON.parse('{"slug":"byudzhet-2027-pensii-mrot-nalog-vklady","locale":"ru","title":"Правительство внесло бюджет на 2027–2029 годы с дефицитом 5,5 трлн рублей в 2027 году","description":"Бюджет на 2027 год: дефицит 5,5 трлн рублей, пенсии +10,3%, МРОТ 28 935 рублей. Кого затронет налог до 22% на вклады и почему дефицит держит ставку.","blocks":[{"id":"b001","kind":"paragraph","text":"Правительство 30 сентября 2026 года внесло в Госдуму бюджет на 2027–2029 годы. В 2027 году государство собирается потратить 48,8 трлн рублей, а получить 43,3 трлн. Разница в 5,5 трлн рублей называется дефицитом бюджета, это 2,2% ВВП. В 2028 и 2029 годах разрыв почти такой же, 5,1 и 5,3 трлн рублей."},{"id":"b002","kind":"paragraph","text":"Пенсии в 2027 году проиндексируют дважды: на 6,8% с 1 февраля и ещё на 3,3% с 1 апреля. Вместе это около 10,3% (1,068 \xd7 1,033), средняя пенсия по старости к концу года составит 29 904 рубля. МРОТ вырастет на 6,8%, до 28 935 рублей, прожиточный минимум до 20 227 рублей. На детей и семьи за три года заложено 10 трлн рублей."},{"id":"b003","kind":"paragraph","text":"Вместе с бюджетом 30 сентября 2026 года в Госдуму внесли поправки в Налоговый кодекс. Проценты по вкладам, дивиденды и доходы от ценных бумаг хотят сложить с зарплатой и облагать по общей шкале от 13% до 22%. Ставка 13% останется для дохода до 2,4 млн рублей в год, это 200 тыс. рублей в месяц. Необлагаемый лимит процентов по вкладам сохранится. По оценке Минфина, изменения коснутся не больше 6% налогоплательщиков, около 4 млн человек."},{"id":"b004","kind":"paragraph","text":"Почему дефицит важен для всех. Возьмём семью, которая зарабатывает 100 тыс. рублей, а тратит 113 тыс. и разницу берёт в долг. У бюджета 2027 года та же пропорция (48,8 / 43,3 = 1,13). Деньги, потраченные сверх доходов, становятся чьими-то зарплатами и покупками. Покупателей с деньгами больше, а товаров столько же, и цены растут быстрее."},{"id":"b005","kind":"paragraph","text":"В тот же день, 30 сентября, Банк России отправил в Госдуму свою стратегию на 2027–2029 годы с отдельным разделом о бюджете. Цель прежняя: инфляция около 4%. Сейчас она выше, 6,3% на 7 сентября, а ключевая ставка 14%. Чем больше государство тратит в долг, тем дольше Банку России держать ставку высокой. От неё зависят проценты по ипотеке, кредитам и вкладам. Следующее решение по ставке 23 октября."},{"id":"b006","kind":"paragraph","text":"Для обычного человека расклад такой. Пенсии вырастут на 10,3%, МРОТ на 6,8%, а инфляцию в 2027 году Банк России ждёт около 4%. Налог на вклады по новой шкале коснётся только тех, у кого доход вместе с процентами больше 2,4 млн рублей в год. Брать ипотеку в расчёте на скорое снижение ставки рискованно, потому что дефицит может его отодвинуть. Откладывать покупку до снижения ставок тоже стоит денег, ведь цены за это время растут. Какие цифры останутся после чтений в Госдуме, пока неизвестно."},{"id":"b007","kind":"heading","text":"Насколько вырастут пенсии в 2027 году?"},{"id":"b008","kind":"paragraph","text":"Страховые пенсии проиндексируют дважды, на 6,8% с 1 февраля и на 3,3% с 1 апреля, вместе примерно на 10,3%. Средняя пенсия по старости к концу 2027 года составит 29 904 рубля."},{"id":"b009","kind":"heading","text":"Будет ли налог 22% на проценты по вкладам?"},{"id":"b010","kind":"paragraph","text":"Только при очень большом доходе. По поправкам, внесённым в Госдуму 30 сентября 2026 года, ставка 13% сохраняется для годового дохода до 2,4 млн рублей вместе с зарплатой, а 22% начинается с 50 млн рублей. Необлагаемый лимит процентов по вкладам остаётся. Закон ещё должны принять."},{"id":"b011","kind":"heading","text":"Какой МРОТ будет в 2027 году?"},{"id":"b012","kind":"paragraph","text":"28 935 рублей, на 6,8% больше, чем сейчас. Прожиточный минимум вырастет до 20 227 рублей."}],"sources":[{"label":"Правительство внесло в Госдуму проект бюджета на следующую трехлетку","url":"https://www.vedomosti.ru/economics/articles/2026/09/30/1233234-proekt-byudzheta-na-20272029-godi"},{"label":"Правительство внесло в Госдуму проект бюджета на 2027–2029 годы","url":"https://www.kommersant.ru/doc/8990879"},{"label":"Правительство внесло в Госдуму проект бюджета на 2027–2029 годы","url":"https://ria.ru/20260930/gosduma-2121326719.html"},{"label":"Правительство внесло бюджет на 2027–2029 годы: расходы, доходы, индексация МРОТ и маткапитала","url":"https://finance.mail.ru/article/pravitelstvo-vneslo-v-gd-proekt-byudzheta-na-20272029-gody-69230340/"},{"label":"Налоги с процентов по вкладам и дохода от инвестиций с 2027 года","url":"https://t-j.ru/taxation-changes/"},{"label":"Налог на вклады до 22%: кого коснется предложение Минфина","url":"https://finuslugi.ru/navigator/nakopit-i-sohranit/stat_nalog-22-na-vklady-komu-gotovitsya"},{"label":"Минфин предложил распространить прогрессивную шкалу НДФЛ на \xabпассивные\xbb доходы","url":"https://amp.rbc.ru/rbcnews/economics/24/09/2026/6ab4dd2e8788480e67fe300e"},{"label":"Проект изменений в Налоговый кодекс включили в бюджетный пакет","url":"https://investfuture.ru/articles/proekt-izmenenii-v-nalogovyi-kodeks-voshel-v-byudzhetnyi-paket-3f16ce8bddcfe833"},{"label":"Банк России сохранил ключевую ставку на уровне 14%","url":"https://www.cbr.ru/press/keypr/"},{"label":"ЦБ направил в Госдуму проект основных направлений ДКП","url":"https://www.vedomosti.ru/economics/news/2026/09/30/1233154-tsb-napravil-gosdumu"}],"sourceBodySha256":"be77690376518f39ef24e28cfc00950eded08b6fb2c56a9ff24881d083267c1d"}')}}]);